  "implementation": "def solve(case):
    import json
    # Validate and extract fields
    if 'min_cluster_size' not in case:
        raise ValueError('Missing min_cluster_size')
    if 'clusters' not in case:
        raise ValueError('Missing clusters')
    if 'parent' not in case:
        raise ValueError('Missing parent')
    min_size = case['min_cluster_size']
    clusters_in = case['clusters']
    parent_map = case['parent']

    if not isinstance(min_size, int) or min_size < 0:
        raise ValueError('min_cluster_size must be a non-negative integer')
    if not isinstance(clusters_in, list):
        raise ValueError('clusters must be a list')
    if not isinstance(parent_map, dict):
        raise ValueError('parent must be a dictionary')

    # Build cluster lookup
    cluster_dict = {}
    for cl in clusters_in:
        if not isinstance(cl, dict):
            raise ValueError('Each cluster must be a dict')
        cid = cl.get('cluster_id')
        if not isinstance(cid, str):
            raise ValueError('cluster_id must be a string')
        size = cl.get('size')
        if not isinstance(size, int):
            raise ValueError('size must be an integer')
        birth = cl.get('birth_lambda')
        if not isinstance(birth, (int, float)):
            raise ValueError('birth_lambda must be a number')
        exits = cl.get('point_exit_lambdas')
        if not isinstance(exits, list) or not all(isinstance(x, (int, float)) for x in exits):
            raise ValueError('point_exit_lambdas must be a list of numbers')
        cluster_dict[cid] = cl

    # Filter clusters by size
    retained = []
    for cl in clusters_in:
        if cl['size'] >= min_size:
            retained.append(cl)

    # Compute stability for each retained cluster
    stability_map = {}
    for cl in retained:
        cid = cl['cluster_id']
        birth = cl['birth_lambda']
        exits = cl['point_exit_lambdas']
        stab = sum(max(0, e - birth) for e in exits)
        stability_map[cid] = stab

    # Sort retained by (-stability, cluster_id) for selection order
    retained_sorted = sorted(retained, key=lambda cl: (-stability_map[cl['cluster_id']], cl['cluster_id']))

    # Build ancestors lookup for any cluster id (including those not retained)
    # We need full parent chain
    def get_ancestors(cid):
        ancestors = []
        cur = parent_map.get(cid)
        while cur is not None:
            ancestors.append(cur)
            cur = parent_map.get(cur)
        return ancestors

    blocked = set()
    selected = []
    for cl in retained_sorted:
        cid = cl['cluster_id']
        if cid in blocked:
            continue
        selected.append(cid)
        # Block all ancestors
        for anc in get_ancestors(cid):
            blocked.add(anc)

    # Build output clusters array (retained in any order, but we'll use retained order)
    clusters_out = []
    for cl in retained:
        cid = cl['cluster_id']
        clusters_out.append({
            'cluster_id': cid,
            'size': cl['size'],
            'stability': stability_map[cid]
        })

    selected_sorted = sorted(selected)
    return {
        'clusters': clusters_out,
        'selected_cluster_ids': selected_sorted
    }"
}
